  it("keeps concurrent onboarding edits but discards readiness for a replaced server (H7)", async () => {
    setConnectionState({
      phase: ConnectionPhase.SEARCHING,
      isConnected: false,
      isChecking: false,
      configStep: "url",
      hasCompletedFirstRun: false,
      userPersona: null,
